    margin-top: -.25em;
    margin-left: -.25em;
    width: .5em;
    height: .5em;
    animation: k-loading-animation reverse 1.4s linear infinite;
}

.k-loading-image::before,
.k-loading-image::after {
    content: "";
    border-width: 1px;
    border-width: clamp(0.015em, 1px, 1px);
    font-size: 4em;
}

@keyframes k-loading-animation {
    0% {
        transform: rotate(0deg);
